// Copies ABIs from the Foundry build into a typed TS module. Run after `forge build`: npm run abi
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const out = resolve(root, "../contracts/out");
const read = (file, name) => JSON.parse(readFileSync(resolve(out, file, `${name}.json`), "utf8")).abi;

const body = [
  "// AUTO-GENERATED by scripts/sync-abi.mjs — do not edit by hand.",
  `export const ajoAbi = ${JSON.stringify(read("Ajo.sol", "Ajo"), null, 2)} as const;`,
  `export const tokenAbi = ${JSON.stringify(read("TestDollar.sol", "TestDollar"), null, 2)} as const;`,
  "",
].join("\n\n");

writeFileSync(resolve(root, "src/lib/abi.ts"), body);
console.log("wrote src/lib/abi.ts");
